schema_json:
{
  "$defs": {
    "CoverageUnit": {
      "description": "One geographic allocation unit (a row) as printed in the PDF.\n\nCarries whatever identifiers the PDF gives that row — any of a bairro\nname, an IBGE setor code, a distrito — plus its interview count. One\nunified row grain across all PDF formats: name-tabular PDFs fill `name`;\nQUAEST/setor PDFs fill `setor_code`; some fill both. Downstream matches\non whichever identifier is present.",
      "properties": {
        "name": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Bairro / localidade name, verbatim, if the row names one. Null for setor-only rows (e.g. per-interview setor microdata).",
          "title": "Name"
        },
        "setor_code": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "IBGE setor censitário code (12-15 digit numeric string) for this row, verbatim, if printed. Null when the row has no setor code. Capture it whenever present — it keys deterministic urban/rural downstream.",
          "title": "Setor Code"
        },
        "distrito": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Distrito / região this row belongs to, if the PDF groups by distrito (e.g. RJ-style REGIÃO/Distrito). Null otherwise.",
          "title": "Distrito"
        },
        "n_entrevistas": {
          "anyOf": [
            {
              "type": "integer"
            },
            {
              "type": "null"
            }
          ],
          "default": null,
          "description": "Interviews allocated to this unit, if stated. Null when not reported. For regional layouts with a 'Total Região' line, report the per-unit count, not the region total.",
          "title": "N Entrevistas"
        }
      },
      "title": "CoverageUnit",
      "type": "object"
    }
  },
  "description": "Raw geographic allocation list from the per-poll bairro/município PDF.\n\nv3: ONE faithful list of the rows as the PDF prints them (`units`), each\ncarrying whatever identifiers appear — bairro name, IBGE setor code,\ndistrito, interview count. No more / no less than the raw: v2's split\nbairros-list + lossy 10-item setor_codes_sample is replaced by this\nsingle row grain, which preserves the name<->setor<->count linkage and\ndrops nothing. Coverage class / rural / regional-structure / distrito\nlists are NOT stored — all derivable downstream (matched IBGE setor\nsituacao + electorate ratio; set of unit distritos). See docs/decisions.md.",
  "properties": {
    "pesquisa_realized": {
      "description": "True normally. False ONLY when the PDF is the 'PESQUISA NÃO REALIZADA' stamp (poll was cancelled). When false, all other fields default to empty/zero.",
      "title": "Pesquisa Realized",
      "type": "boolean"
    },
    "units": {
      "description": "Every DISTINCT geographic allocation unit the PDF lists, in printed order, each with the identifiers that row carries (name / setor_code / distrito / n_entrevistas). Dedup to the finest printed unit: for per-interview setor microdata, emit one unit per distinct setor with its interview count (NOT one row per interview). HARD CAP 80 units (token budget); if more, keep the 80 with the largest n_entrevistas and record the true count in n_units_total. Empty only for a not-realized stamp.",
      "items": {
        "$ref": "#/$defs/CoverageUnit"
      },
      "title": "Units",
      "type": "array"
    },
    "n_units_total": {
      "default": 0,
      "description": "Total distinct allocation units in the PDF (may exceed len(units) if truncated). 0 when none are listed.",
      "title": "N Units Total",
      "type": "integer"
    },
    "total_interviews_distributed": {
      "default": 0,
      "description": "Sum of n_entrevistas across all units if reported. 0 if interview counts are not given. Should match the poll's QT_ENTREVISTADO when fully reported.",
      "title": "Total Interviews Distributed",
      "type": "integer"
    },
    "extraction_notes": {
      "default": "",
      "description": "Free-form notes on ambiguity, format unusual, or PDF truncation. Flag here if the PDF is text-thin (likely an image-only scan that needs OCR).",
      "title": "Extraction Notes",
      "type": "string"
    }
  },
  "required": [
    "pesquisa_realized"
  ],
  "title": "PollBairroDetail",
  "type": "object"
}
